import styled from '@emotion/styled';

export const StyledBigNumberItem = styled.div({
  '& > div:first-of-type': {
    height: '100%',
  },
  flex: 'calc(50% - 16px)',
});

interface StyledBigNumberContainerProps {
  $loading?: boolean;
}

export const StyledBigNumberContainer =
  styled.div<StyledBigNumberContainerProps>(({ $loading }) => ({
    display: 'flex',
    gap: '16px',
    flexWrap: 'wrap',

    ...($loading === true && {
      '& > div': {
        flexWrap: 'wrap',
      },
    }),
  }));

export const StyledChartHeaderContainer = styled.div({
  minWidth: '90px',
});
